```js
async function resolveGroup(api, flags) {
  const wanted = String(flags.group ?? '').trim()
  const lists = await api.getLists()
  if (!Array.isArray(lists) || lists.length === 0) throw ...
  const wantedList = String(flags.list ?? '').trim()
  let candidates = lists
  if (wantedList) {
    const found = matchList(lists, wantedList)
    if (!found) throw new CliError('找不到学习列表「...」...')
    candidates = [found]
  }
  const loaded = await Promise.all(candidates.map(list => loadListGroups(api, list)))
  const matches = []
  for (const entry of loaded) {
    const group = findGroup(entry.groups, wanted)
    if (group) matches.push({ ...entry, group })
  }
  if (matches.length === 1) return matches[0]
  if (matches.length > 1) {
    throw new CliError('分组「' + wanted + '」在多个学习列表里：'
      + matches.map(m => m.list.name + '（' + m.list.id + '）').join('、')
      + '。请加 --list 指定一个列表。')
  }
  // 未找到：列出候选，帮助用户发现可用分组
  const available = loaded.filter(e => e.groups.length > 0)
  const detail = available.length === 0
    ? '这些列表里还没有分组。'
    : '现有分组：\n' + available.map(e => '  ' + e.list.name + '（' + e.list.id + '）\n'
        + e.groups.map(g => '    ' + g.key + '  ' + g.label + '（' + g.items.length + ' 词）').join('\n')).join('\n')
  throw new CliError('找不到分组「' + wanted + '」。' + detail)
}
```
