async function commandGroups(context) {
  const { api, flags } = context
  const lists = await api.getLists()
  if (!Array.isArray(lists) || lists.length === 0) throw new CliError('线上还没有学习列表。')
  let targets = lists
  if (String(flags.list ?? '').trim()) {
    const wanted = String(flags.list).trim()
    const found = matchList(lists, wanted)
    if (!found) throw new CliError(...)
    targets = [found]
  }
  const loaded = await Promise.all(targets.map(list => loadListGroups(api, list)))
  const output = loaded.map(({ list, groups }) => ({
    id: list.id,
    name: list.name,
    wordCount: list.wordCount,
    groups: groups.map(group => ({ key: group.key, label: group.label, count: group.items.length, words: group.items.map(item => item.word) })),
  }))
  if (flags.json) { context.json({ ok: true, command: 'groups', lists: output }); return }
  console.log('学习列表分组（' + output.length + ' 个列表）')
  for (const entry of output) {
    console.log('')
    console.log(entry.name + '（' + entry.id + '）· ' + entry.groups.length + ' 组')
    if (entry.groups.length === 0) { console.log('  （还没有分组）'); continue }
    for (const group of entry.groups) {
      console.log('  ' + group.key + '  ' + group.label + '  · ' + group.count + ' 词')
    }
  }
}
```
