    if (!found) {
      throw new CliError('找不到学习列表「' + listWanted + '」。现有列表：'
        + lists.map(list => list.name + '（' + list.id + '）').join('、'))
    }
    candidates = [found]
  }
  const loaded = await Promise.all(candidates.map(list => loadListGroups(api, list)))
  const matches = []
